  for (let c = 0; c < SIZE; c++) {
    const t = grid[r][c];
    if (!t) continue;
    if (mergedTiles.includes(t)) {
      // Merged tile: it takes the element of the first tile in the pair
      const first = t.mergedFrom[0];
      t.el = first.el || null;
      if (t.el) {
        // Fall through: ensure value text is updated below
      }
      if (!t.el) {
        t.el = document.createElement('div');
        t.el.className = 'tile';
        boardEl.appendChild(t.el);
      }
      renderTile(t, r, c, 'merged');
      // The second tile of the pair has been removed; its element is already gone
    } else {
      renderTile(t, r, c);
    }
  }
}

// Element of the second merged tile must be removed (not the one we reused)
mergedTiles.forEach(t => {
  t.mergedFrom.forEach(src => {
    if (src.el && src.el !== t.el && src.el.isConnected) src.el.remove();
  });
});

